text:
{
 "reason": {
  "es": "この法律《ほうりつ》の案《あん》を出《だ》した衆議院《しゅうぎいん》の厚生労働委員会《こうせいろうどういいんかい》は、つぎのように説明《せつめい》しています。社会保険労務士《しゃかいほけんろうむし》（会社《かいしゃ》の人《ひと》の仕事《しごと》や保険《ほけん》の手続《てつづ》きなどを助《たす》ける専門家《せんもんか》）のしくみをとりまくようすが、さいきん変《か》わってきました。そこで、いくつかのことをする必要《ひつよう》があるためです。社会保険労務士《しゃかいほけんろうむし》の役目《やくめ》（使命《しめい》）をはっきりさせるきまりをつくります。仕事《しごと》に「労務《ろうむ》監査《かんさ》」（はたらき方《かた》のきまりが守《まも》られているかを調《しら》べること）がふくまれることを書《か》きます。裁判所《さいばんしょ》にいっしょに行《い》く弁護士《べんごし》の立場《たちば》を「代理人《だいりにん》」に変《か》えます。まぎらわしい名前《なまえ》のれいとして「社労士《しゃろうし》」などをくわえます。",
  "hs": "提出した衆議院厚生労働委員会は、最近の社会保険労務士制度を取り巻く状況《じょうきょう》の変化をふまえ、社会保険労務士の使命を明らかにする規定を設け、業務に労務｜監査《かんさ》（労働に関する法令などが守られているかを調べること）が含《ふく》まれることを明記し、裁判所にともに出頭する弁護士の地位を代理人に改め、名称《めいしょう》の使用制限の類似｜名称《めいしょう》の例として社労士などを加える必要があるためとしている。",
  "std": "提出した衆議院厚生労働委員会は、最近の社会保険労務士制度を取り巻く状況の変化を踏まえ、社会保険労務士の使命を明らかにする規定を設け、業務に労務監査が含まれることを明記し、裁判所にともに出頭する弁護士の地位を代理人に改め、名称の使用制限に係る類似名称の例示として社労士等を追加する必要があるためとしている。",
  "univ": "提出した衆議院厚生労働委員会は、最近における社会保険労務士制度を取り巻く状況の変化に鑑み、社会保険労務士の使命を明らかにする規定を設け、社会保険労務士の業務に労務監査が含まれることを明記し、社会保険労務士が裁判所にともに出頭することとされている弁護士の地位を代理人に改め、及び名称の使用制限に係る類似名称の例示として社労士等を追加する必要があるためとしている。"
 },
 "who": {
  "es": "社会保険労務士《しゃかいほけんろうむし》。社会保険労務士法人《しゃかいほけんろうむしほうじん》。社会保険労務士会《しゃかいほけんろうむしかい》と、全国社会保険労務士会連合会《ぜんこくしゃかいほけんろうむしかいれんごうかい》。社会保険労務士《しゃかいほけんろうむし》が裁判所《さいばんしょ》に行《い》くとき、いっしょに行《い》く弁護士《べんごし》。社会保険労務士《しゃかいほけんろうむし》などではないのに、「社労士《しゃろうし》」などのまぎらわしい名前《なまえ》を使《つか》ってはいけない人《ひと》や団体《だんたい》。",
  "hs": "社会保険労務士、社会保険労務士法人、社会保険労務士会と全国社会保険労務士会連合会、社会保険労務士が補佐人として出頭するときにともに出頭する弁護士、「社労士」などの類似｜名称《めいしょう》を使ってはならない社会保険労務士などでない者や団体。",
  "std": "社会保険労務士、社会保険労務士法人、社会保険労務士会・全国社会保険労務士会連合会、社会保険労務士が補佐人として出頭する際にともに出頭する弁護士、「社労士」等の類似名称を用いてはならない社会保険労務士等でない者・団体。",
  "univ": "社会保険労務士、社会保険労務士法人、社会保険労務士会及び全国社会保険労務士会連合会、社会保険労務士が裁判所に補佐人として出頭し陳述をする場合に裁判所にともに出頭することとされている弁護士、「社労士」「社労士法人」「社労士会」「全国社労士会連合会」の類似名称を用いてはならない社会保険労務士等でない者及び団体。"
 },
 "committee": {
  "es": "この法律《ほうりつ》の案《あん》は、衆議院《しゅうぎいん》の厚生労働委員会《こうせいろうどういいんかい》が出《だ》したものです。6月《がつ》6日《か》の委員会《いいんかい》で、賛成《さんせい》が多《おお》く、委員会《いいんかい》から出《だ》す法律《ほうりつ》の案《あん》にすることが決《き》まりました。参議院《さんぎいん》では、厚生労働委員会《こうせいろうどういいんかい》で話《はな》し合《あ》いました。出《だ》した人《ひと》である衆議院《しゅうぎいん》の厚生《こうせい》労働《ろうどう》委員長《いいんちょう》の藤丸敏《ふじまるさとし》さんから、説明《せつめい》を聞《き》きました。そのあと、社会保険労務士《しゃかいほけんろうむし》の不正《ふせい》などへの対応《たいおう》などについて質問《しつもん》をしました。討論《とうろん》では、れいわ新選組《しんせんぐみ》が反対《はんたい》、日本共産党《にほんきょうさんとう》が賛成《さんせい》の意見《いけん》を述《の》べました。採決《さいけつ》の結果《けっか》、賛成《さんせい》が多《おお》く、そのまま通《とお》すべきものとされました。",
  "hs": "本案は、6月6日の衆議院厚生労働委員会で、賛成多数で委員会提出の法律案とすることが決まったもの。参議院厚生労働委員会では、提出者の衆議院厚生労働委員長・藤丸敏《ふじまるさとし》さんから趣旨《しゅし》説明を聞いた後、社会保険労務士の不正事案などへの対応などについて質疑を行った。討論では、れいわ新選組が反対、日本共産党が賛成の意見を述べ、採決の結果、多数で原案どおり可決すべきものとした。",
  "std": "本案は、6月6日の衆議院厚生労働委員会で、賛成多数で委員会提出法律案とすることが決まったもの。参議院厚生労働委員会では、提出者の衆議院厚生労働委員長藤丸敏氏から趣旨説明を聴取した後、社会保険労務士の不正事案等への対応などについて質疑を行った。討論では、れいわ新選組が反対、日本共産党が賛成の意見を述べ、採決の結果、多数で原案どおり可決すべきものとした。",
  "univ": "本案は、去る6月6日の衆議院厚生労働委員会において、賛成多数をもって委員会提出法律案とすることに決したもの。参議院厚生労働委員会においては、提出者である衆議院厚生労働委員長藤丸敏君より趣旨説明を聴取した後、社会保険労務士の不正事案等への対応等について質疑が行われた。質疑を終局し、討論に入ったところ、れいわ新選組を代表して天畠大輔委員より反対、日本共産党を代表して倉林明子委員より賛成の旨の意見がそれぞれ述べられ、討論を終局し、採決の結果、多数をもって原案どおり可決すべきものと決定した。"
 },
 "views": [
  {
   "side": "賛成",
   "group": "日本共産党",
   "where": "参議院 厚生労働委員会",
   "text": {
    "es": "日本共産党《にほんきょうさんとう》は、賛成《さんせい》しました。新《あたら》しくつくる社会保険労務士《しゃかいほけんろうむし》の役目《やくめ》のきまりに、はたらく人《ひと》のくらしをよくすることなどが書《か》かれたことをあげました。いっぽうで、はたらく人《ひと》の権利《けんり》をおかす事例《じれい》が起《お》きていると述《の》べました。罰《ばつ》のしくみをきびしくすることなどや、もめごとが複雑《ふくざつ》になるのをふせぐしくみを求《もと》めました。",
    "hs": "日本共産党は、新設の使命規定に労働者等の福祉《ふくし》の向上と社会保障の向上・増進に役立つ役割が明記されたとして賛成した。一方で、特定社労士による労働者の権利｜侵害《しんがい》の事案が起きているとし、懲戒処分《ちょうかいしょぶん》制度の厳格化や、労働争議の複雑化を防ぐ仕組みの充実《じゅうじつ》を求めた。",
    "std": "日本共産党は、新設の使命規定に労働者等の福祉の向上や社会保障の向上・増進に資する役割が明記されたとして賛成した。一方、特定社労士による労働者の権利侵害の事案が発生しているとし、懲戒処分制度の厳格化や、労働争議の複雑化を防ぐ仕組みの充実を求めた。",
    "univ": "日本共産党は、新設された使命の規定で、事業の健全な発達にとどまらず、労働者等の福祉の向上並びに社会保障の向上、増進に資する役割が求められることが明記されたとして賛成した。一方、特定社労士による労働者の権利侵害を行う事案が発生しているとし、懲戒処分制度の厳格化などの措置と、社労士の介入による労働争議の複雑化を防ぐ仕組みの充実を求めた。"
   }
  },
  {
   "side": "反対",
   "group": "れいわ新選組",
   "where": "参議院 厚生労働委員会",
   "text": {
    "es": "れいわ新選組《しんせんぐみ》は、反対《はんたい》しました。多《おお》くの社会保険労務士《しゃかいほけんろうむし》は役目《やくめ》にそってはたらいていると述《の》べました。いっぽうで、一部《いちぶ》の社会保険労務士《しゃかいほけんろうむし》が、人権《じんけん》をおかす発言《はつげん》や暴力《ぼうりょく》を行《おこな》っていると述《の》べました。悪《わる》い行《おこな》いをした社会保険労務士《しゃかいほけんろうむし》に重《おも》い罰《ばつ》をあたえる法律《ほうりつ》づくりと運用《うんよう》が、急《いそ》いで必要《ひつよう》だとしました。社会保険労務士《しゃかいほけんろうむし》が自分《じぶん》たちで悪《わる》いところを正《ただ》す力《ちから》（自浄能力《じじょうのうりょく》）が高《たか》まることに期待《きたい》すると述《の》べました。",
    "hs": "れいわ新選組は、多くの社労士は使命に基づいて働いているとしたうえで、一部の社労士が反人権的な発言や暴力行為《ぼうりょくこうい》を行っていると述べて反対した。悪質な行為《こうい》を行う社労士を厳しく処罰《しょばつ》する法整備と運用が急務だとし、社労士自身の自浄能力《じじょうのうりょく》（自分たちで悪いところを正す力）の向上に期待するとした。",
    "std": "れいわ新選組は、全国の社労士の大部分は使命に基づき尽力しているとした上で、一部の社労士が反人権的な発言や暴力行為を行っていると述べて反対した。悪質な行為を行う社労士を厳罰に処する法整備と運用が急務だとし、社労士自身の自浄能力の向上に期待するとした。",
    "univ": "れいわ新選組は、全国に3万8千人いる社労士の大部分が既に使命に基づいて日々尽力しているとした上で、一部の社労士が反人権的言辞や暴力行為を働いているとして反対した。悪質な行為を行う社労士を厳罰に処する法整備と運用が急務だとし、社会保険労務士自身の自浄能力の向上に期待すると述べた。"
   }
  }
 ],
 "no_debate": false
}
